insert into public.places (slug,name,latitude,longitude,region,type,description,cover_media_id,photos,best_months,best_time,tips,coordinates_approximate,sort_order,seo,is_placeholder,published) values ('colombo','Colombo',6.9271,79.8612,'Western coast','City','Oceanfront walks, market streets and a lively food scene make Colombo a gentle introduction to island life. Leave room for a sunset stroll and an unhurried first meal.',(select id from public.media where slug='landscape-coast'),array[(select id from public.media where slug='landscape-coast')]::uuid[],array['December','January','February','March','April']::text[],'Early morning or late afternoon; seasonal guidance is illustrative and must be confirmed.','Visit markets earlier in the day. Allow extra time for city traffic.',true,0,'{"title": "Colombo | Visit Sri Lanka — Demo", "description": "Oceanfront walks, market streets and a lively food scene make Colombo a gentle introduction to island life. Leave room for a sunset stroll and an unhurried first meal."}'::jsonb,true,true) on conflict(slug) do update set name=excluded.name,latitude=excluded.latitude,longitude=excluded.longitude,region=excluded.region,type=excluded.type,description=excluded.description,cover_media_id=excluded.cover_media_id,photos=excluded.photos,best_months=excluded.best_months,best_time=excluded.best_time,tips=excluded.tips,coordinates_approximate=excluded.coordinates_approximate,sort_order=excluded.sort_order,seo=excluded.seo,is_placeholder=excluded.is_placeholder,published=excluded.published;
insert into public.places (slug,name,latitude,longitude,region,type,description,cover_media_id,photos,best_months,best_time,tips,coordinates_approximate,sort_order,seo,is_placeholder,published) values ('sigiriya','Sigiriya',7.957,80.7603,'Cultural Triangle','Culture','A dramatic rock rises above gardens and green plains. Explore the wider landscape at a slower pace, with village paths and a memorable view across the Cultural Triangle.',(select id from public.media where slug='landscape-sigiriya'),array[(select id from public.media where slug='landscape-sigiriya')]::uuid[],array['December','January','February','March','April']::text[],'Early morning or late afternoon; seasonal guidance is illustrative and must be confirmed.','Start early to avoid the midday heat. Wear secure shoes and carry water.',true,1,'{"title": "Sigiriya | Visit Sri Lanka — Demo", "description": "A dramatic rock rises above gardens and green plains. Explore the wider landscape at a slower pace, with village paths and a memorable view across the Cultural Triangle."}'::jsonb,true,true) on conflict(slug) do update set name=excluded.name,latitude=excluded.latitude,longitude=excluded.longitude,region=excluded.region,type=excluded.type,description=excluded.description,cover_media_id=excluded.cover_media_id,photos=excluded.photos,best_months=excluded.best_months,best_time=excluded.best_time,tips=excluded.tips,coordinates_approximate=excluded.coordinates_approximate,sort_order=excluded.sort_order,seo=excluded.seo,is_placeholder=excluded.is_placeholder,published=excluded.published;
insert into public.places (slug,name,latitude,longitude,region,type,description,cover_media_id,photos,best_months,best_time,tips,coordinates_approximate,sort_order,seo,is_placeholder,published) values ('kandy','Kandy',7.2906,80.6337,'Central hills','Culture','Set around a lake and encircled by green hills, Kandy blends sacred spaces, busy streets and botanical escapes. Take time for a lakeside walk between cultural visits.',(select id from public.media where slug='landscape-tea'),array[(select id from public.media where slug='landscape-tea')]::uuid[],array['December','January','February','March','April']::text[],'Early morning or late afternoon; seasonal guidance is illustrative and must be confirmed.','Dress respectfully at temples and follow local photography guidance.',true,2,'{"title": "Kandy | Visit Sri Lanka — Demo", "description": "Set around a lake and encircled by green hills, Kandy blends sacred spaces, busy streets and botanical escapes. Take time for a lakeside walk between cultural visits."}'::jsonb,true,true) on conflict(slug) do update set name=excluded.name,latitude=excluded.latitude,longitude=excluded.longitude,region=excluded.region,type=excluded.type,description=excluded.description,cover_media_id=excluded.cover_media_id,photos=excluded.photos,best_months=excluded.best_months,best_time=excluded.best_time,tips=excluded.tips,coordinates_approximate=excluded.coordinates_approximate,sort_order=excluded.sort_order,seo=excluded.seo,is_placeholder=excluded.is_placeholder,published=excluded.published;
insert into public.places (slug,name,latitude,longitude,region,type,description,cover_media_id,photos,best_months,best_time,tips,coordinates_approximate,sort_order,seo,is_placeholder,published) values ('nuwara-eliya','Nuwara Eliya',6.9497,80.7891,'Hill country','Tea country','Cool air, rolling plantations and misty horizons give the highlands a quieter rhythm. Follow tea-country roads, pause at viewpoints and settle into an evening with a warm cup.',(select id from public.media where slug='landscape-tea'),array[(select id from public.media where slug='landscape-tea')]::uuid[],array['January','February','March']::text[],'Early morning or late afternoon; seasonal guidance is illustrative and must be confirmed.','Pack a light rain layer and something warm for cool evenings.',true,3,'{"title": "Nuwara Eliya | Visit Sri Lanka — Demo", "description": "Cool air, rolling plantations and misty horizons give the highlands a quieter rhythm. Follow tea-country roads, pause at viewpoints and settle into an evening with a warm cup."}'::jsonb,true,true) on conflict(slug) do update set name=excluded.name,latitude=excluded.latitude,longitude=excluded.longitude,region=excluded.region,type=excluded.type,description=excluded.description,cover_media_id=excluded.cover_media_id,photos=excluded.photos,best_months=excluded.best_months,best_time=excluded.best_time,tips=excluded.tips,coordinates_approximate=excluded.coordinates_approximate,sort_order=excluded.sort_order,seo=excluded.seo,is_placeholder=excluded.is_placeholder,published=excluded.published;
insert into public.places (slug,name,latitude,longitude,region,type,description,cover_media_id,photos,best_months,best_time,tips,coordinates_approximate,sort_order,seo,is_placeholder,published) values ('ella','Ella',6.8667,81.0466,'Hill country','Hiking','Ella pairs green ridgelines with relaxed village life. Walk to viewpoints, watch a train cross the Nine Arch Bridge and leave an afternoon free to simply enjoy the hills.',(select id from public.media where slug='landscape-ella'),array[(select id from public.media where slug='landscape-ella')]::uuid[],array['January','February','March']::text[],'Early morning or late afternoon; seasonal guidance is illustrative and must be confirmed.','Stay off railway tracks; use public viewpoints and check walking conditions.',true,4,'{"title": "Ella | Visit Sri Lanka — Demo", "description": "Ella pairs green ridgelines with relaxed village life. Walk to viewpoints, watch a train cross the Nine Arch Bridge and leave an afternoon free to simply enjoy the hills."}'::jsonb,true,true) on conflict(slug) do update set name=excluded.name,latitude=excluded.latitude,longitude=excluded.longitude,region=excluded.region,type=excluded.type,description=excluded.description,cover_media_id=excluded.cover_media_id,photos=excluded.photos,best_months=excluded.best_months,best_time=excluded.best_time,tips=excluded.tips,coordinates_approximate=excluded.coordinates_approximate,sort_order=excluded.sort_order,seo=excluded.seo,is_placeholder=excluded.is_placeholder,published=excluded.published;
insert into public.places (slug,name,latitude,longitude,region,type,description,cover_media_id,photos,best_months,best_time,tips,coordinates_approximate,sort_order,seo,is_placeholder,published) values ('mirissa','Mirissa',5.9485,80.4716,'South coast','Beach','A sweep of sand and palm-lined bays invites a slower finish to your journey. Enjoy a coastal walk, a fresh lunch and the changing colours of the Indian Ocean.',(select id from public.media where slug='landscape-coast'),array[(select id from public.media where slug='landscape-coast')]::uuid[],array['December','January','February','March','April']::text[],'Early morning or late afternoon; seasonal guidance is illustrative and must be confirmed.','Sea conditions vary. Swim only where local guidance says it is safe.',true,5,'{"title": "Mirissa | Visit Sri Lanka — Demo", "description": "A sweep of sand and palm-lined bays invites a slower finish to your journey. Enjoy a coastal walk, a fresh lunch and the changing colours of the Indian Ocean."}'::jsonb,true,true) on conflict(slug) do update set name=excluded.name,latitude=excluded.latitude,longitude=excluded.longitude,region=excluded.region,type=excluded.type,description=excluded.description,cover_media_id=excluded.cover_media_id,photos=excluded.photos,best_months=excluded.best_months,best_time=excluded.best_time,tips=excluded.tips,coordinates_approximate=excluded.coordinates_approximate,sort_order=excluded.sort_order,seo=excluded.seo,is_placeholder=excluded.is_placeholder,published=excluded.published;
insert into public.places (slug,name,latitude,longitude,region,type,description,cover_media_id,photos,best_months,best_time,tips,coordinates_approximate,sort_order,seo,is_placeholder,published) values ('galle','Galle',6.0329,80.2168,'South coast','Heritage','Walkable lanes, ocean-facing ramparts and small courtyards make Galle a lovely place to wander. Pause for coffee, browse independent shops and stay for the evening light.',(select id from public.media where slug='landscape-coast'),array[(select id from public.media where slug='landscape-coast')]::uuid[],array['December','January','February','March','April']::text[],'Early morning or late afternoon; seasonal guidance is illustrative and must be confirmed.','The ramparts can be hot and exposed. Bring water and respect residential streets.',true,6,'{"title": "Galle | Visit Sri Lanka — Demo", "description": "Walkable lanes, ocean-facing ramparts and small courtyards make Galle a lovely place to wander. Pause for coffee, browse independent shops and stay for the evening light."}'::jsonb,true,true) on conflict(slug) do update set name=excluded.name,latitude=excluded.latitude,longitude=excluded.longitude,region=excluded.region,type=excluded.type,description=excluded.description,cover_media_id=excluded.cover_media_id,photos=excluded.photos,best_months=excluded.best_months,best_time=excluded.best_time,tips=excluded.tips,coordinates_approximate=excluded.coordinates_approximate,sort_order=excluded.sort_order,seo=excluded.seo,is_placeholder=excluded.is_placeholder,published=excluded.published;
insert into public.places (slug,name,latitude,longitude,region,type,description,cover_media_id,photos,best_months,best_time,tips,coordinates_approximate,sort_order,seo,is_placeholder,published) values ('anuradhapura','Anuradhapura',8.3114,80.4037,'Cultural Triangle','Culture','Sacred trees, stupas and broad archaeological landscapes tell layered stories of the ancient capital. Give each site room to breathe rather than racing between monuments.',(select id from public.media where slug='landscape-sigiriya'),array[(select id from public.media where slug='landscape-sigiriya')]::uuid[],array['December','January','February','March','April']::text[],'Early morning or late afternoon; seasonal guidance is illustrative and must be confirmed.','Carry socks for hot temple grounds; shoulders and knees should be covered.',true,7,'{"title": "Anuradhapura | Visit Sri Lanka — Demo", "description": "Sacred trees, stupas and broad archaeological landscapes tell layered stories of the ancient capital. Give each site room to breathe rather than racing between monuments."}'::jsonb,true,true) on conflict(slug) do update set name=excluded.name,latitude=excluded.latitude,longitude=excluded.longitude,region=excluded.region,type=excluded.type,description=excluded.description,cover_media_id=excluded.cover_media_id,photos=excluded.photos,best_months=excluded.best_months,best_time=excluded.best_time,tips=excluded.tips,coordinates_approximate=excluded.coordinates_approximate,sort_order=excluded.sort_order,seo=excluded.seo,is_placeholder=excluded.is_placeholder,published=excluded.published;
insert into public.places (slug,name,latitude,longitude,region,type,description,cover_media_id,photos,best_months,best_time,tips,coordinates_approximate,sort_order,seo,is_placeholder,published) values ('polonnaruwa','Polonnaruwa',7.9403,81.0188,'Cultural Triangle','Culture','Explore a landscape of stone figures, reservoirs and ancient courtyards. A patient morning here reveals fine details and a sense of the scale of the former royal city.',(select id from public.media where slug='landscape-sigiriya'),array[(select id from public.media where slug='landscape-sigiriya')]::uuid[],array['December','January','February','March','April']::text[],'Early morning or late afternoon; seasonal guidance is illustrative and must be confirmed.','Choose early hours and carry plenty of water. Confirm ticket and guide arrangements locally.',true,8,'{"title": "Polonnaruwa | Visit Sri Lanka — Demo", "description": "Explore a landscape of stone figures, reservoirs and ancient courtyards. A patient morning here reveals fine details and a sense of the scale of the former royal city."}'::jsonb,true,true) on conflict(slug) do update set name=excluded.name,latitude=excluded.latitude,longitude=excluded.longitude,region=excluded.region,type=excluded.type,description=excluded.description,cover_media_id=excluded.cover_media_id,photos=excluded.photos,best_months=excluded.best_months,best_time=excluded.best_time,tips=excluded.tips,coordinates_approximate=excluded.coordinates_approximate,sort_order=excluded.sort_order,seo=excluded.seo,is_placeholder=excluded.is_placeholder,published=excluded.published;
insert into public.places (slug,name,latitude,longitude,region,type,description,cover_media_id,photos,best_months,best_time,tips,coordinates_approximate,sort_order,seo,is_placeholder,published) values ('dambulla','Dambulla',7.8567,80.6492,'Cultural Triangle','Culture','Rock shelters and painted interiors make Dambulla an atmospheric cultural stop. The climb opens views over the surrounding plains before the quiet of the temple spaces.',(select id from public.media where slug='landscape-sigiriya'),array[(select id from public.media where slug='landscape-sigiriya')]::uuid[],array['December','January','February','March','April']::text[],'Early morning or late afternoon; seasonal guidance is illustrative and must be confirmed.','Modest clothing is essential; check current visitor access and photography rules.',true,9,'{"title": "Dambulla | Visit Sri Lanka — Demo", "description": "Rock shelters and painted interiors make Dambulla an atmospheric cultural stop. The climb opens views over the surrounding plains before the quiet of the temple spaces."}'::jsonb,true,true) on conflict(slug) do update set name=excluded.name,latitude=excluded.latitude,longitude=excluded.longitude,region=excluded.region,type=excluded.type,description=excluded.description,cover_media_id=excluded.cover_media_id,photos=excluded.photos,best_months=excluded.best_months,best_time=excluded.best_time,tips=excluded.tips,coordinates_approximate=excluded.coordinates_approximate,sort_order=excluded.sort_order,seo=excluded.seo,is_placeholder=excluded.is_placeholder,published=excluded.published;
insert into public.places (slug,name,latitude,longitude,region,type,description,cover_media_id,photos,best_months,best_time,tips,coordinates_approximate,sort_order,seo,is_placeholder,published) values ('unawatuna','Unawatuna',6.0104,80.2497,'South coast','Beach','A sheltered-looking bay, leafy lanes and nearby coastal walks offer an easy beach stop close to Galle. Balance time on the sand with a little exploring beyond the main street.',(select id from public.media where slug='landscape-coast'),array[(select id from public.media where slug='landscape-coast')]::uuid[],array['December','January','February','March','April']::text[],'Early morning or late afternoon; seasonal guidance is illustrative and must be confirmed.','A calm-looking sea is not a guarantee of safe swimming; follow local advice.',true,10,'{"title": "Unawatuna | Visit Sri Lanka — Demo", "description": "A sheltered-looking bay, leafy lanes and nearby coastal walks offer an easy beach stop close to Galle. Balance time on the sand with a little exploring beyond the main street."}'::jsonb,true,true) on conflict(slug) do update set name=excluded.name,latitude=excluded.latitude,longitude=excluded.longitude,region=excluded.region,type=excluded.type,description=excluded.description,cover_media_id=excluded.cover_media_id,photos=excluded.photos,best_months=excluded.best_months,best_time=excluded.best_time,tips=excluded.tips,coordinates_approximate=excluded.coordinates_approximate,sort_order=excluded.sort_order,seo=excluded.seo,is_placeholder=excluded.is_placeholder,published=excluded.published;
insert into public.places (slug,name,latitude,longitude,region,type,description,cover_media_id,photos,best_months,best_time,tips,coordinates_approximate,sort_order,seo,is_placeholder,published) values ('tissamaharama','Tissamaharama',6.2791,81.287,'Southern plains','Nature','Lakeside paths, birdlife and open plains make this a peaceful base for the southeast. Enjoy the changing light over the water before an early wildlife outing.',(select id from public.media where slug='landscape-yala'),array[(select id from public.media where slug='landscape-yala')]::uuid[],array['December','January','February','March','April']::text[],'Early morning or late afternoon; seasonal guidance is illustrative and must be confirmed.','Keep a respectful distance from wildlife and arrange safari logistics in advance.',true,11,'{"title": "Tissamaharama | Visit Sri Lanka — Demo", "description": "Lakeside paths, birdlife and open plains make this a peaceful base for the southeast. Enjoy the changing light over the water before an early wildlife outing."}'::jsonb,true,true) on conflict(slug) do update set name=excluded.name,latitude=excluded.latitude,longitude=excluded.longitude,region=excluded.region,type=excluded.type,description=excluded.description,cover_media_id=excluded.cover_media_id,photos=excluded.photos,best_months=excluded.best_months,best_time=excluded.best_time,tips=excluded.tips,coordinates_approximate=excluded.coordinates_approximate,sort_order=excluded.sort_order,seo=excluded.seo,is_placeholder=excluded.is_placeholder,published=excluded.published;
insert into public.places (slug,name,latitude,longitude,region,type,description,cover_media_id,photos,best_months,best_time,tips,coordinates_approximate,sort_order,seo,is_placeholder,published) values ('yala','Yala',6.373,81.5185,'Southeast','Wildlife','Dry forest, scrub and waterholes create an ever-changing wildlife landscape. A patient safari is about the habitat as much as any individual sighting; nothing is guaranteed.',(select id from public.media where slug='landscape-yala'),array[(select id from public.media where slug='landscape-yala')]::uuid[],array['December','January','February','March','April']::text[],'Early morning or late afternoon; seasonal guidance is illustrative and must be confirmed.','Seasonal access can change. Never feed animals or ask a driver to crowd wildlife.',true,12,'{"title": "Yala | Visit Sri Lanka — Demo", "description": "Dry forest, scrub and waterholes create an ever-changing wildlife landscape. A patient safari is about the habitat as much as any individual sighting; nothing is guaranteed."}'::jsonb,true,true) on conflict(slug) do update set name=excluded.name,latitude=excluded.latitude,longitude=excluded.longitude,region=excluded.region,type=excluded.type,description=excluded.description,cover_media_id=excluded.cover_media_id,photos=excluded.photos,best_months=excluded.best_months,best_time=excluded.best_time,tips=excluded.tips,coordinates_approximate=excluded.coordinates_approximate,sort_order=excluded.sort_order,seo=excluded.seo,is_placeholder=excluded.is_placeholder,published=excluded.published;
insert into public.places (slug,name,latitude,longitude,region,type,description,cover_media_id,photos,best_months,best_time,tips,coordinates_approximate,sort_order,seo,is_placeholder,published) values ('haputale','Haputale',6.7654,80.9513,'Hill country','Tea country','Tea slopes fall away into layered valleys around this hill-country town. Slow drives and early viewpoints are the reward, with cloud and light constantly reshaping the landscape.',(select id from public.media where slug='landscape-tea'),array[(select id from public.media where slug='landscape-tea')]::uuid[],array['January','February','March']::text[],'Early morning or late afternoon; seasonal guidance is illustrative and must be confirmed.','Viewpoints are clearest early, but fog can arrive quickly. Use established paths.',true,13,'{"title": "Haputale | Visit Sri Lanka — Demo", "description": "Tea slopes fall away into layered valleys around this hill-country town. Slow drives and early viewpoints are the reward, with cloud and light constantly reshaping the landscape."}'::jsonb,true,true) on conflict(slug) do update set name=excluded.name,latitude=excluded.latitude,longitude=excluded.longitude,region=excluded.region,type=excluded.type,description=excluded.description,cover_media_id=excluded.cover_media_id,photos=excluded.photos,best_months=excluded.best_months,best_time=excluded.best_time,tips=excluded.tips,coordinates_approximate=excluded.coordinates_approximate,sort_order=excluded.sort_order,seo=excluded.seo,is_placeholder=excluded.is_placeholder,published=excluded.published;
insert into public.places (slug,name,latitude,longitude,region,type,description,cover_media_id,photos,best_months,best_time,tips,coordinates_approximate,sort_order,seo,is_placeholder,published) values ('horton-plains','Horton Plains',6.8021,80.8072,'Hill country','Hiking','High grasslands and cloud forest offer a different side of the island. An early walk gives the landscape time to unfold, with weather and trail conditions shaping the day.',(select id from public.media where slug='landscape-tea'),array[(select id from public.media where slug='landscape-tea')]::uuid[],array['January','February','March']::text[],'Early morning or late afternoon; seasonal guidance is illustrative and must be confirmed.','Check park access and trail conditions. Carry layers and take all litter with you.',true,14,'{"title": "Horton Plains | Visit Sri Lanka — Demo", "description": "High grasslands and cloud forest offer a different side of the island. An early walk gives the landscape time to unfold, with weather and trail conditions shaping the day."}'::jsonb,true,true) on conflict(slug) do update set name=excluded.name,latitude=excluded.latitude,longitude=excluded.longitude,region=excluded.region,type=excluded.type,description=excluded.description,cover_media_id=excluded.cover_media_id,photos=excluded.photos,best_months=excluded.best_months,best_time=excluded.best_time,tips=excluded.tips,coordinates_approximate=excluded.coordinates_approximate,sort_order=excluded.sort_order,seo=excluded.seo,is_placeholder=excluded.is_placeholder,published=excluded.published;
insert into public.places (slug,name,latitude,longitude,region,type,description,cover_media_id,photos,best_months,best_time,tips,coordinates_approximate,sort_order,seo,is_placeholder,published) values ('bentota','Bentota',6.425,79.9951,'Southwest coast','Beach','River scenery meets long coastal stretches on the southwest shore. Break a road journey with a riverside pause or choose a quiet afternoon near the ocean.',(select id from public.media where slug='landscape-coast'),array[(select id from public.media where slug='landscape-coast')]::uuid[],array['December','January','February','March','April']::text[],'Early morning or late afternoon; seasonal guidance is illustrative and must be confirmed.','Check water conditions and choose responsible, licensed activity providers.',true,15,'{"title": "Bentota | Visit Sri Lanka — Demo", "description": "River scenery meets long coastal stretches on the southwest shore. Break a road journey with a riverside pause or choose a quiet afternoon near the ocean."}'::jsonb,true,true) on conflict(slug) do update set name=excluded.name,latitude=excluded.latitude,longitude=excluded.longitude,region=excluded.region,type=excluded.type,description=excluded.description,cover_media_id=excluded.cover_media_id,photos=excluded.photos,best_months=excluded.best_months,best_time=excluded.best_time,tips=excluded.tips,coordinates_approximate=excluded.coordinates_approximate,sort_order=excluded.sort_order,seo=excluded.seo,is_placeholder=excluded.is_placeholder,published=excluded.published;
insert into public.places (slug,name,latitude,longitude,region,type,description,cover_media_id,photos,best_months,best_time,tips,coordinates_approximate,sort_order,seo,is_placeholder,published) values ('negombo','Negombo',7.2083,79.8358,'Western coast','City','Lagoon views and a long beach make Negombo a useful place to ease into travel after a flight. Start slowly with a coastal walk and a simple local meal.',(select id from public.media where slug='landscape-coast'),array[(select id from public.media where slug='landscape-coast')]::uuid[],array['December','January','February','March','April']::text[],'Early morning or late afternoon; seasonal guidance is illustrative and must be confirmed.','Allow for airport traffic and keep the arrival day flexible.',true,16,'{"title": "Negombo | Visit Sri Lanka — Demo", "description": "Lagoon views and a long beach make Negombo a useful place to ease into travel after a flight. Start slowly with a coastal walk and a simple local meal."}'::jsonb,true,true) on conflict(slug) do update set name=excluded.name,latitude=excluded.latitude,longitude=excluded.longitude,region=excluded.region,type=excluded.type,description=excluded.description,cover_media_id=excluded.cover_media_id,photos=excluded.photos,best_months=excluded.best_months,best_time=excluded.best_time,tips=excluded.tips,coordinates_approximate=excluded.coordinates_approximate,sort_order=excluded.sort_order,seo=excluded.seo,is_placeholder=excluded.is_placeholder,published=excluded.published;
