insert into public.itinerary_days (slug,tour_id,day_number,title,description,locations,travel_time,photos,sort_order,is_placeholder,published) values ('classic-seven-day-island-circuit-day-1',(select id from public.tours where slug='classic-seven-day-island-circuit'),1,'Arrival by the ocean','Settle in after your flight. Explore a little of Colombo at your own pace, then meet over dinner to shape the week ahead. Sample timings and activities require local confirmation.','Colombo','1–2 hours approximate',array[(select id from public.media where slug='landscape-Oceanfront walks, market streets and a lively food scene make Colombo a gentle introduction to island life. Leave room for a sunset stroll and an unhurried first meal.')]::uuid[],0,true,true) on conflict(slug) do update set tour_id=excluded.tour_id,day_number=excluded.day_number,title=excluded.title,description=excluded.description,locations=excluded.locations,travel_time=excluded.travel_time,photos=excluded.photos,sort_order=excluded.sort_order,is_placeholder=excluded.is_placeholder,published=excluded.published;
