insert into public.page_sections (slug,page_id,type,content,sort_order,is_placeholder,published) values ('privacy-intro',(select id from public.pages where slug='privacy'),'rich_text','{"heading": "", "body": "Generic draft for owner and legal review. This is not legal advice.\n\nWe collect the details you voluntarily submit, including your name, contact information, travel preferences and message, to respond to your inquiry. Do not include sensitive personal information.\n\nInquiry information is stored with our hosting and database providers and is available only to the authorized site administrator. We do not sell inquiry details. Contact the business using the published contact address to request access, correction or deletion.\n\nThis site remembers appearance and cookie-notice preferences in your browser. Interactive maps load third-party OpenStreetMap tiles, which receive your network address. If enabled, Cloudflare Turnstile processes information to prevent abuse.\n\nThe owner must confirm legal identity, retention periods, international transfers, lawful basis and applicable privacy rights before launch."}'::jsonb,0,true,true) on conflict(slug) do update set page_id=excluded.page_id,type=excluded.type,content=excluded.content,sort_order=excluded.sort_order,is_placeholder=excluded.is_placeholder,published=excluded.published;
insert into public.pages (slug,title,sort_order,seo,is_placeholder,published) values ('terms','Terms — draft',11,'{"title": "Terms — draft | Visit Sri Lanka — Demo", "description": "Generic draft for owner and legal review.\n\nThis website is a showcase and inquiry service. Sending an inquiry does not create a booking. No payment is accepted on this website.\n\nSample routes, prices, travel times, photographs and availability are illustrative. A booking is forme"}'::jsonb,true,true) on conflict(slug) do update set title=excluded.title,sort_order=excluded.sort_order,seo=excluded.seo,is_placeholder=excluded.is_placeholder,published=excluded.published;
insert into public.page_sections (slug,page_id,type,content,sort_order,is_placeholder,published) values ('terms-intro',(select id from public.pages where slug='terms'),'rich_text','{"heading": "", "body": "Generic draft for owner and legal review.\n\nThis website is a showcase and inquiry service. Sending an inquiry does not create a booking. No payment is accepted on this website.\n\nSample routes, prices, travel times, photographs and availability are illustrative. A booking is formed only under a separate written agreement confirmed by the operator. Verify inclusions, exclusions, insurance, accessibility, entry requirements and safety conditions before travel.\n\nThird-party services and external links have their own conditions. Nothing in these draft terms limits rights that cannot lawfully be excluded. The owner must add the contracting business details, governing law and a reviewed dispute process before using these terms."}'::jsonb,0,true,true) on conflict(slug) do update set page_id=excluded.page_id,type=excluded.type,content=excluded.content,sort_order=excluded.sort_order,is_placeholder=excluded.is_placeholder,published=excluded.published;
insert into public.pages (slug,title,sort_order,seo,is_placeholder,published) values ('cancellation','Cancellation — draft',12,'{"title": "Cancellation — draft | Visit Sri Lanka — Demo", "description": "Generic draft for owner and legal review.\n\nThere are no bookings or payments on this website. Cancellation terms must be agreed in the operator’s written proposal before a booking is confirmed.\n\nSupplier rules, deposits, refund deadlines and changes depend on the services arrange"}'::jsonb,true,true) on conflict(slug) do update set title=excluded.title,sort_order=excluded.sort_order,seo=excluded.seo,is_placeholder=excluded.is_placeholder,published=excluded.published;
insert into public.page_sections (slug,page_id,type,content,sort_order,is_placeholder,published) values ('cancellation-intro',(select id from public.pages where slug='cancellation'),'rich_text','{"heading": "", "body": "Generic draft for owner and legal review.\n\nThere are no bookings or payments on this website. Cancellation terms must be agreed in the operator’s written proposal before a booking is confirmed.\n\nSupplier rules, deposits, refund deadlines and changes depend on the services arranged. Ask for an itemized cancellation schedule and details of any non-refundable third-party costs.\n\nContact the operator promptly in writing if plans change. Refund eligibility and timing must be confirmed under the final agreement and applicable law. This sample page does not promise a refund or set a cancellation fee."}'::jsonb,0,true,true) on conflict(slug) do update set page_id=excluded.page_id,type=excluded.type,content=excluded.content,sort_order=excluded.sort_order,is_placeholder=excluded.is_placeholder,published=excluded.published;
insert into public.page_sections (slug,page_id,type,content,sort_order,is_placeholder,published) values ('home-intro',(select id from public.pages where slug='home'),'hero','{"heading": "Sri Lanka.\nCloser to wonder.", "eyebrow": "AN ISLAND. A THOUSAND POSSIBILITIES.", "body": "Misty hills. Ancient stories. Endless blue.\nFind a journey that moves at your pace.", "cta_label": "Explore the journeys", "cta_href": "/tours", "secondary_label": "Plan your trip", "secondary_href": "/contact", "scroll_label": "A little more to discover"}'::jsonb,0,true,true) on conflict(slug) do update set page_id=excluded.page_id,type=excluded.type,content=excluded.content,sort_order=excluded.sort_order,is_placeholder=excluded.is_placeholder,published=excluded.published;
