insert into public.page_sections (slug,page_id,type,content,sort_order,is_placeholder,published) values ('home-why-us',(select id from public.pages where slug='home'),'why_us','{"heading": "Less rushing. More feeling.", "body": "A thoughtful approach to an island full of possibilities.", "items": [{"title": "A pace that feels like you", "body": "Make room for slow mornings, spontaneous stops and the things you came to discover."}, {"title": "Journeys with a little depth", "body": "Connect landscapes with stories, familiar highlights with small moments beyond the itinerary."}, {"title": "Start with a conversation", "body": "Share your ideas before committing. A personal proposal should make every detail clear."}]}'::jsonb,2,true,true) on conflict(slug) do update set page_id=excluded.page_id,type=excluded.type,content=excluded.content,sort_order=excluded.sort_order,is_placeholder=excluded.is_placeholder,published=excluded.published;
