insert into public.faqs (slug,question,answer,category,sort_order,is_placeholder,published) values ('demo-faq-1','Can the route be tailored?','Yes, this demo is built around adaptable sample journeys. Tell the operator your dates, interests and preferred pace, and request a written proposal.','Planning your journey',0,true,true) on conflict(slug) do update set question=excluded.question,answer=excluded.answer,category=excluded.category,sort_order=excluded.sort_order,is_placeholder=excluded.is_placeholder,published=excluded.published;
insert into public.faqs (slug,question,answer,category,sort_order,is_placeholder,published) values ('demo-faq-2','Are the prices confirmed?','No. All displayed prices are illustrative demo amounts in USD, not live quotations. Accommodation, season, group size and inclusions affect the final proposal.','Planning your journey',1,true,true) on conflict(slug) do update set question=excluded.question,answer=excluded.answer,category=excluded.category,sort_order=excluded.sort_order,is_placeholder=excluded.is_placeholder,published=excluded.published;
