insert into public.faqs (slug,question,answer,category,sort_order,is_placeholder,published) values ('demo-faq-4','Will train tickets and wildlife sightings be guaranteed?','No. Train services, ticket availability, park access and wildlife sightings can change. Ask about alternatives before confirming your plans.','Planning your journey',3,true,true) on conflict(slug) do update set question=excluded.question,answer=excluded.answer,category=excluded.category,sort_order=excluded.sort_order,is_placeholder=excluded.is_placeholder,published=excluded.published;
insert into public.faqs (slug,question,answer,category,sort_order,is_placeholder,published) values ('demo-faq-5','What should I pack for the hills?','Comfortable shoes, a light rain layer and a warm layer are useful. Check the forecast and the requirements of your planned walks before travelling.','Planning your journey',4,true,true) on conflict(slug) do update set question=excluded.question,answer=excluded.answer,category=excluded.category,sort_order=excluded.sort_order,is_placeholder=excluded.is_placeholder,published=excluded.published;
insert into public.faqs (slug,question,answer,category,sort_order,is_placeholder,published) values ('demo-faq-6','What should I wear at cultural sites?','Dress respectfully, with shoulders and knees covered where required. Follow current local guidance on shoes, photography and access.','Planning your journey',5,true,true) on conflict(slug) do update set question=excluded.question,answer=excluded.answer,category=excluded.category,sort_order=excluded.sort_order,is_placeholder=excluded.is_placeholder,published=excluded.published;
