insert into public.blog_posts (slug,title,excerpt,content,author_name,cover_media_id,published_at,sort_order,seo,is_placeholder,published) values ('the-art-of-slow-travel','The art of travelling a little slower','Why an unplanned hour can be the most memorable part of your journey.','{"body": "Start with space, not a checklist. A route feels different when there is room to linger over breakfast or stop because the view caught your eye.\n\nIn the hills, let the journey become part of the day. Watch the cloud lift from a valley, choose a short walk rather than a second long drive, and ask a local host what they enjoy about the place.\n\nAlong the coast, give yourself an evening without an agenda. A walk in the changing light can be enough.\n\nDraft inspiration article for demo use. Activities, access and safety guidance must be verified before travel."}'::jsonb,'Visit Sri Lanka — demo editorial',(select id from public.media where slug='landscape-tea'),'2026-09-01T08:00:00Z',0,'{"title": "The art of travelling a little slower | Island notes — Demo", "description": "Why an unplanned hour can be the most memorable part of your journey."}'::jsonb,true,true) on conflict(slug) do update set title=excluded.title,excerpt=excluded.excerpt,content=excluded.content,author_name=excluded.author_name,cover_media_id=excluded.cover_media_id,published_at=excluded.published_at,sort_order=excluded.sort_order,seo=excluded.seo,is_placeholder=excluded.is_placeholder,published=excluded.published;
insert into public.blog_posts (slug,title,excerpt,content,author_name,cover_media_id,published_at,sort_order,seo,is_placeholder,published) values ('a-first-journey-around-sri-lanka','Your first island journey, thoughtfully connected','Culture, tea country and coast: finding a rhythm that feels right for you.','{"body": "Begin with the experiences that matter most. Ancient sites, a scenic rail segment and time beside the ocean can sit comfortably in the same journey when the route allows realistic travel time.\n\nChoose fewer bases and more breathing room. The island is compact on a map, but hill-country roads, traffic and weather all influence a day.\n\nTreat rail travel as a flexible chapter, with reservations and alternatives confirmed in advance. Finish somewhere that lets the week settle into memory.\n\nThis is a draft demo story, not current transport or booking advice."}'::jsonb,'Visit Sri Lanka — demo editorial',(select id from public.media where slug='landscape-sigiriya'),'2026-09-01T08:00:00Z',1,'{"title": "Your first island journey, thoughtfully connected | Island notes — Demo", "description": "Culture, tea country and coast: finding a rhythm that feels right for you."}'::jsonb,true,true) on conflict(slug) do update set title=excluded.title,excerpt=excluded.excerpt,content=excluded.content,author_name=excluded.author_name,cover_media_id=excluded.cover_media_id,published_at=excluded.published_at,sort_order=excluded.sort_order,seo=excluded.seo,is_placeholder=excluded.is_placeholder,published=excluded.published;
insert into public.blog_posts (slug,title,excerpt,content,author_name,cover_media_id,published_at,sort_order,seo,is_placeholder,published) values ('coast-with-a-little-culture','Salt air, old walls and coastal pauses','A few ways to make a south-coast escape more than a beach stop.','{"body": "A coastal journey can hold many different moods. Begin with a slow morning, take a shaded walk through heritage streets, and leave the warmest hours for rest.\n\nIn Galle, enjoy the lanes as a living neighbourhood as well as a place to explore. Be considerate around homes, take your litter away and ask before photographing people.\n\nAt the beach, choose the view before choosing to swim. Follow current local safety advice and give the sea the respect it deserves.\n\nDraft demo inspiration only. Opening hours, sea conditions and local guidance change."}'::jsonb,'Visit Sri Lanka — demo editorial',(select id from public.media where slug='landscape-coast'),'2026-09-01T08:00:00Z',2,'{"title": "Salt air, old walls and coastal pauses | Island notes — Demo", "description": "A few ways to make a south-coast escape more than a beach stop."}'::jsonb,true,true) on conflict(slug) do update set title=excluded.title,excerpt=excluded.excerpt,content=excluded.content,author_name=excluded.author_name,cover_media_id=excluded.cover_media_id,published_at=excluded.published_at,sort_order=excluded.sort_order,seo=excluded.seo,is_placeholder=excluded.is_placeholder,published=excluded.published;
insert into private.mock_cleanup_queue(storage_path) select storage_path from public.media where is_placeholder on conflict do nothing;
