update public.page_sections set content=content||jsonb_build_object('image',(select id from public.media where slug='landscape-ella')) where slug='home-intro';
update public.page_sections set content=content||jsonb_build_object('image',(select id from public.media where slug='landscape-tea')) where slug='home-guide-story';
update public.page_sections set content=content||jsonb_build_object('photos',(select jsonb_agg(id order by slug) from public.media where slug in ('landscape-coast','landscape-yala','landscape-sigiriya'))) where slug='home-island-gallery';
alter table public.reviews disable trigger review_submission_guard;
alter table public.reviews enable trigger review_submission_guard;
update public.nav_items set label=replace(label,'[PLACEHOLDER] ',''),is_placeholder=true; update public.footer_links set label=replace(label,'[PLACEHOLDER] ',''),is_placeholder=true;

-- Preserve provenance when an editor saves a sample as published.
create function private.retain_mock_origin() returns trigger language plpgsql set search_path='' as $$
begin if old.is_placeholder then new.is_placeholder:=true; end if; return new; end $$;
revoke all on function private.retain_mock_origin() from public,anon,authenticated;
do $$ declare t text; begin
foreach t in array array['site_settings','nav_items','footer_links','pages','page_sections','media','tours','itinerary_days','places','route_stops','vehicles','team_members','reviews','blog_posts','faqs'] loop
execute format('create trigger retain_mock_origin before update on public.%I for each row execute function private.retain_mock_origin()',t);
end loop; end $$;

alter table public.inquiries add column tour_snapshot text not null default '';
-- Never accept a visitor-supplied private snapshot.
create function private.guard_inquiry_snapshot() returns trigger language plpgsql security definer set search_path='' as $$
begin if not private.is_admin() and new.tour_snapshot<>'' then raise exception 'Invalid inquiry'; end if; return new; end $$;
revoke all on function private.guard_inquiry_snapshot() from public,anon,authenticated;
create trigger inquiry_snapshot_guard before insert on public.inquiries for each row execute function private.guard_inquiry_snapshot();

create table private.mock_cleanup_queue(storage_path text primary key check(storage_path ~ '^[a-f0-9-]{36}\.(webp|png|jpg|jpeg|mp4|webm)$'),created_at timestamptz not null default now());
alter table private.mock_cleanup_queue enable row level security;
grant select,insert,delete on private.mock_cleanup_queue to authenticated;
create policy cleanup_admin_read on private.mock_cleanup_queue for select to authenticated using ((select private.is_admin()));
create policy cleanup_admin_insert on private.mock_cleanup_queue for insert to authenticated with check ((select private.is_admin()));
create policy cleanup_admin_delete on private.mock_cleanup_queue for delete to authenticated using ((select private.is_admin()));

create function public.mock_data_status() returns jsonb language plpgsql security invoker set search_path='' as $$
declare t text; n bigint; counts jsonb:='{}'; begin
if not private.is_admin() then raise exception 'Forbidden' using errcode='42501'; end if;
foreach t in array array['site_settings','nav_items','footer_links','pages','page_sections','media','tours','itinerary_days','places','route_stops','vehicles','team_members','reviews','blog_posts','faqs'] loop
execute format('select count(*) from public.%I where is_placeholder',t) into n;
counts:=counts||jsonb_build_object(t,n); end loop;
return jsonb_build_object('counts',counts,'pending',(select count(*) from private.mock_cleanup_queue)); end $$;

create function public.remove_mock_data() returns jsonb language plpgsql security invoker set search_path='' as $$
declare t text; ids text[]:='{}'; more text[]; blocked boolean; n bigint; counts jsonb:='{}';
tables constant text[]:=array['site_settings','nav_items','footer_links','pages','page_sections','media','tours','itinerary_days','places','route_stops','vehicles','team_members','reviews','blog_posts','faqs'];
begin
if not private.is_admin() then raise exception 'Forbidden' using errcode='42501'; end if;
-- One transaction and shared ordering prevent concurrent content edits while checking references.
foreach t in array tables loop execute format('lock table public.%I in share row exclusive mode',t); end loop;
foreach t in array tables loop
execute format('select coalesce(array_agg(id::text),array[]::text[]) from public.%I where is_placeholder',t) into more; ids:=ids||more; end loop;
foreach t in array tables loop
execute format('select exists(select 1 from public.%I r where not r.is_placeholder and exists(select 1 from unnest($1) id where strpos(to_jsonb(r)::text,id)>0))',t) into blocked using ids;
if blocked then raise exception 'Real content references mock content. Replace those references before removing samples.'; end if;
end loop;
-- Keep private inquiry context when a sample tour is removed; no inquiry rows are deleted.
update public.inquiries i set tour_snapshot=t.title from public.tours t where i.tour_id=t.id and t.is_placeholder;
foreach t in array array['route_stops','itinerary_days','page_sections','reviews','faqs','blog_posts','team_members','vehicles','tours','places','nav_items','footer_links','pages','site_settings','media'] loop
execute format('delete from public.%I where is_placeholder',t); get diagnostics n=row_count; counts:=counts||jsonb_build_object(t,n); end loop;
return counts; end $$;

create function public.pending_mock_media() returns setof text language plpgsql security invoker set search_path='' as $$
begin if not private.is_admin() then raise exception 'Forbidden' using errcode='42501'; end if;
return query select storage_path from private.mock_cleanup_queue order by storage_path limit 100; end $$;
create function public.acknowledge_mock_media(paths text[]) returns void language plpgsql security invoker set search_path='' as $$
begin if not private.is_admin() then raise exception 'Forbidden' using errcode='42501'; end if;
if cardinality(paths)>100 then raise exception 'Invalid batch'; end if;
delete from private.mock_cleanup_queue where storage_path=any(paths); end $$;
revoke all on function public.mock_data_status(),public.remove_mock_data(),public.pending_mock_media(),public.acknowledge_mock_media(text[]) from public,anon;
grant execute on function public.mock_data_status(),public.remove_mock_data(),public.pending_mock_media(),public.acknowledge_mock_media(text[]) to authenticated;

